import { NOW, priorities } from './data'
import type { Agent, Priority, Status, Ticket } from './data'

export type View = 'all' | Status

export const views: { id: View; label: string }[] = [
  { id: 'open', label: 'Open' },
  { id: 'pending', label: 'Pending' },
  { id: 'solved', label: 'Solved' },
  { id: 'all', label: 'All' },
]

export const inView = (ticket: Ticket, view: View) =>
  view === 'all' || ticket.status === view

/** Urgent first: a lower rank sorts higher */
export const priorityRank = (p: Priority) => priorities.indexOf(p)

export interface Changes {
  status?: Status
  priority?: Priority
  assignee?: Agent
}

/** One ticket with new field values; the rest untouched */
export const updateTicket = (
  tickets: Ticket[],
  id: string,
  changes: Changes,
): Ticket[] =>
  tickets.map((t) => (t.id === id ? { ...t, ...changes, updated: NOW } : t))

/**
 * Adds the agent's reply. An open ticket becomes pending, since it now
 * waits on the customer.
 */
export const replyTo = (
  tickets: Ticket[],
  id: string,
  author: string,
  body: string,
): Ticket[] =>
  tickets.map((t) =>
    t.id === id
      ? {
          ...t,
          status: t.status === 'open' ? 'pending' : t.status,
          updated: NOW,
          messages: [
            ...t.messages,
            { from: 'agent', author, at: NOW, body: body.trim() },
          ],
        }
      : t,
  )

// Minutes since an epoch for a time like "2026-11-17T09:40"; no Date, so no time zones
const minutes = (at: string) => {
  const [date, time] = at.split('T')
  const [y, m, d] = date.split('-').map(Number)
  const [h, mi] = time.split(':').map(Number)
  return Date.UTC(y, m - 1, d, h, mi) / 60_000
}

/** "just now", "25m ago", "3h ago", "2d ago" */
export function timeAgo(at: string) {
  const diff = minutes(NOW) - minutes(at)
  if (diff < 1) return 'just now'
  if (diff < 60) return `${diff}m ago`
  if (diff < 24 * 60) return `${Math.floor(diff / 60)}h ago`
  return `${Math.floor(diff / (24 * 60))}d ago`
}

const months = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
]

/** "Nov 17, 09:40" */
export function formatTime(at: string) {
  const [date, time] = at.split('T')
  const [, m, d] = date.split('-').map(Number)
  return `${months[m - 1]} ${d}, ${time}`
}

export const initials = (name: string) =>
  name
    .split(' ')
    .map((part) => part[0])
    .join('')
    .slice(0, 2)

import { ArrowDown, ArrowUp } from 'lucide-react'
import type { Column, ColumnDef, Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { cn } from '#/lib/utils'
import type { Priority, Status, Ticket } from './data'
import { inView, priorityRank, timeAgo } from './tickets'
import type { View } from './tickets'

/**
 * A ticket plus the values it sorts by. They match the ticket, except for
 * the open one, which keeps the values it had when it was opened: editing
 * it in the panel then doesn't send its row to another page.
 */
export type TicketRow = Ticket & { sortAs: Ticket }

export interface TicketMeta {
  /** The ticket shown in the panel */
  openId: string | null
  /** The status filter, to say when the open ticket no longer matches it */
  view: View
  open: (id: string) => void
}

const getMeta = (table: Table<TicketRow>) =>
  table.options.meta as unknown as TicketMeta

/** The status filter, plus the open ticket, which stays while it's open */
export interface StatusFilter {
  view: View
  keep: string | null
}

export const statusStyle: Record<Status, { label: string; className: string }> =
  {
    open: {
      label: 'Open',
      className: 'border-blue-500/40 text-blue-700 dark:text-blue-400',
    },
    pending: {
      label: 'Pending',
      className: 'border-amber-500/50 text-amber-800 dark:text-amber-300',
    },
    solved: { label: 'Solved', className: 'text-muted-foreground' },
  }

export const priorityStyle: Record<Priority, { label: string; dot: string }> = {
  urgent: { label: 'Urgent', dot: 'bg-red-500' },
  high: { label: 'High', dot: 'bg-orange-400' },
  normal: { label: 'Normal', dot: 'bg-sky-500' },
  low: { label: 'Low', dot: 'bg-muted-foreground/40' },
}

export function StatusBadge({ status }: { status: Status }) {
  const style = statusStyle[status]
  return (
    <Badge variant="outline" className={style.className}>
      {style.label}
    </Badge>
  )
}

export function PriorityLabel({ priority }: { priority: Priority }) {
  const style = priorityStyle[priority]
  return (
    <span className="flex items-center gap-1.5 whitespace-nowrap">
      <span aria-hidden className={cn('size-2 rounded-full', style.dot)} />
      {style.label}
    </span>
  )
}

function SortHeader({
  column,
  label,
}: {
  column: Column<TicketRow>
  label: string
}) {
  const sorted = column.getIsSorted()
  const Icon = sorted === 'desc' ? ArrowDown : ArrowUp
  return (
    <button
      type="button"
      onClick={column.getToggleSortingHandler()}
      className="group/sort inline-flex items-center gap-1 rounded-sm outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50"
    >
      {label}
      <Icon
        aria-hidden
        className={cn(
          'size-3.5',
          !sorted && 'opacity-0 group-hover/sort:opacity-40',
        )}
      />
    </button>
  )
}

export const columns: ColumnDef<TicketRow>[] = [
  {
    id: 'subject',
    header: 'Ticket',
    cell: ({ row, table }) => {
      const meta = getMeta(table)
      const ticket = row.original
      const isOpen = meta.openId === ticket.id
      return (
        <div className="flex min-w-0 flex-col gap-0.5">
          <button
            type="button"
            data-ticket-id={ticket.id}
            aria-expanded={isOpen}
            aria-controls="ticket-panel"
            onClick={() => meta.open(ticket.id)}
            className="truncate rounded-sm text-left font-medium outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50"
          >
            {ticket.subject}
          </button>
          <span className="truncate text-xs text-muted-foreground">
            <span className="font-mono">{ticket.id}</span> ·{' '}
            {ticket.customer.name}, {ticket.customer.company}
          </span>
          {isOpen && !inView(ticket, meta.view) ? (
            <span className="text-xs text-amber-700 dark:text-amber-400">
              No longer {meta.view}: leaves this list when you close it
            </span>
          ) : null}
        </div>
      )
    },
  },
  {
    id: 'status',
    header: 'Status',
    accessorFn: (t) => t.status,
    filterFn: (row, _id, { view, keep }: StatusFilter) =>
      row.original.id === keep || inView(row.original, view),
    cell: ({ row }) => <StatusBadge status={row.original.status} />,
  },
  {
    id: 'priority',
    accessorFn: (t) => priorityRank(t.sortAs.priority),
    header: ({ column }) => <SortHeader column={column} label="Priority" />,
    // Ascending rank is urgent first, which is what a first click should do
    sortDescFirst: false,
    cell: ({ row }) => <PriorityLabel priority={row.original.priority} />,
  },
  {
    id: 'assignee',
    header: 'Assignee',
    cell: ({ row }) => (
      <span
        className={cn(
          'whitespace-nowrap',
          row.original.assignee === 'Unassigned' && 'text-muted-foreground',
        )}
      >
        {row.original.assignee}
      </span>
    ),
  },
  {
    id: 'updated',
    accessorFn: (t) => t.sortAs.updated,
    header: ({ column }) => <SortHeader column={column} label="Updated" />,
    cell: ({ row }) => (
      <span className="whitespace-nowrap text-muted-foreground tabular-nums">
        {timeAgo(row.original.updated)}
      </span>
    ),
  },
]

import { useMemo } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type {
  OnChangeFn,
  PaginationState,
  SortingState,
  Table as TanStackTable,
} from '@tanstack/react-table'

import { Button } from '#/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { StatusFilter, TicketMeta, TicketRow } from './columns'
import type { Ticket } from './data'
import type { View } from './tickets'

export const PAGE_SIZE = 8

/**
 * The table lives in the demo, not in the component that draws it: the
 * panel's previous and next buttons need its sorted, filtered order.
 */
export function useTicketTable({
  tickets,
  pinned,
  view,
  sorting,
  onSortingChange,
  pagination,
  onPaginationChange,
  meta,
}: {
  tickets: Ticket[]
  /** The open ticket as it was when opened; it sorts by these values */
  pinned: Ticket | null
  view: View
  sorting: SortingState
  onSortingChange: OnChangeFn<SortingState>
  pagination: PaginationState
  onPaginationChange: OnChangeFn<PaginationState>
  meta: TicketMeta
}) {
  // Memoized: a new array every render would count as a filter change
  const columnFilters = useMemo(
    () => [
      {
        id: 'status',
        value: { view, keep: meta.openId } satisfies StatusFilter,
      },
    ],
    [view, meta.openId],
  )

  const data = useMemo<TicketRow[]>(
    () =>
      tickets.map((t) => ({
        ...t,
        sortAs: pinned && t.id === pinned.id ? pinned : t,
      })),
    [tickets, pinned],
  )

  return useReactTable({
    data,
    columns,
    getRowId: (ticket) => ticket.id,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    state: { sorting, pagination, columnFilters },
    onSortingChange,
    onPaginationChange,
    // Editing a ticket or opening one must not move you to page 1; the demo
    // resets the page itself when the filter changes
    autoResetPageIndex: false,
    meta,
  })
}

// With the panel open there is less room, and the panel shows priority and
// assignee anyway, so those two columns step aside
const narrow: Record<string, string> = {
  assignee: 'hidden',
  priority: 'hidden',
}

export function TicketTable({
  table,
  panelOpen,
}: {
  table: TanStackTable<TicketRow>
  panelOpen: boolean
}) {
  const openId = (table.options.meta as TicketMeta).openId
  const rows = table.getRowModel().rows
  const { pageIndex } = table.getState().pagination
  const total = table.getPrePaginationRowModel().rows.length
  const hide = (id: string) =>
    panelOpen ? narrow[id] : id === 'assignee' ? 'hidden md:table-cell' : ''

  return (
    <div className="flex min-w-0 flex-1 flex-col">
      {/* Scrolls on its own, so opening a ticket never moves the page */}
      <div className="max-h-[32rem] min-h-[28rem] flex-1 overflow-auto">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id} className="hover:bg-transparent">
                {group.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    aria-sort={
                      header.column.getIsSorted() === 'asc'
                        ? 'ascending'
                        : header.column.getIsSorted() === 'desc'
                          ? 'descending'
                          : undefined
                    }
                    className={hide(header.column.id)}
                  >
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {rows.length ? (
              rows.map((row) => {
                const isOpen = row.id === openId
                return (
                  <TableRow
                    key={row.id}
                    data-ticket-row={row.id}
                    aria-current={isOpen ? 'true' : undefined}
                    className={cn(
                      isOpen &&
                        'bg-muted shadow-[inset_3px_0_0_var(--color-primary)] hover:bg-muted',
                    )}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell
                        key={cell.id}
                        className={cn(
                          hide(cell.column.id),
                          cell.column.id === 'subject' && 'w-full max-w-0',
                        )}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                )
              })
            ) : (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={columns.length}
                  className="h-40 text-center text-muted-foreground"
                >
                  No tickets here.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-between gap-2 border-t px-3 py-2">
        <p className="text-sm text-muted-foreground tabular-nums">
          {total
            ? `${pageIndex * PAGE_SIZE + 1}–${Math.min(total, (pageIndex + 1) * PAGE_SIZE)} of ${total}`
            : 'No tickets'}
        </p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import type { RefObject } from 'react'
import { ChevronDown, ChevronUp, SendHorizontal, X } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Label } from '#/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils'
import { agents, priorities, statuses } from './data'
import type { Ticket } from './data'
import { PriorityLabel, statusStyle } from './columns'
import { formatTime, initials } from './tickets'
import type { Changes } from './tickets'

interface PanelProps {
  /** The ticket to show, or null when the panel is closed */
  ticket: Ticket | null
  /** "3 of 9" in the current filter and sort */
  position: { index: number; total: number }
  onPrevious?: () => void
  onNext?: () => void
  onClose: () => void
  onChange: (changes: Changes) => void
  onReply: (body: string) => void
  /** Where focus goes on close when the ticket's row is gone */
  fallbackFocus: () => void
}

export function TicketPanel(props: PanelProps) {
  const { ticket, onClose, fallbackFocus } = props
  // Keeps the last ticket on screen while the panel slides out
  const [shown, setShown] = useState(ticket)
  if (ticket && ticket !== shown) setShown(ticket)

  const open = ticket !== null
  const panel = useRef<HTMLElement>(null)
  const heading = useRef<HTMLHeadingElement>(null)
  const openId = ticket?.id ?? null
  const lastId = useRef(openId)

  useEffect(() => {
    if (openId) {
      // Opened from the table: announce the ticket by focusing its subject.
      // Switched with the panel's own buttons: leave focus where it is.
      if (!panel.current?.contains(document.activeElement))
        heading.current?.focus()
    } else if (lastId.current) {
      // Closed: back to the subject that opened it
      const row = document.querySelector<HTMLElement>(
        `[data-ticket-id="${lastId.current}"]`,
      )
      if (row) row.focus()
      else fallbackFocus()
    }
    lastId.current = openId
  }, [openId, fallbackFocus])

  return (
    <section
      ref={panel}
      id="ticket-panel"
      aria-label="Ticket details"
      aria-hidden={!open}
      inert={!open}
      onKeyDown={(e) => {
        // Escape in a Select's list (rendered elsewhere in the page) closes
        // only the list, not the panel
        if (e.key === 'Escape' && panel.current?.contains(e.target as Node))
          onClose()
      }}
      className={cn(
        'shrink-0 overflow-hidden bg-background duration-300 ease-out motion-reduce:transition-none max-sm:absolute max-sm:inset-y-0 max-sm:right-0 max-sm:z-20',
        // Pushes the table aside as it widens (on phones it covers it instead).
        // Visible at once when opening, so the heading can take focus; hidden
        // only after closing, so it can't be tabbed to while closed
        open
          ? 'visible w-full border-l transition-[width] sm:w-[26rem]'
          : 'invisible w-0 transition-[width,visibility]',
      )}
    >
      {/* A fixed width inside, so the content doesn't reflow while it widens */}
      <div className="flex h-full w-full flex-col sm:w-[26rem]">
        {shown ? (
          <TicketBody {...props} ticket={shown} headingRef={heading} />
        ) : null}
      </div>
    </section>
  )
}

function TicketBody({
  ticket,
  position,
  onPrevious,
  onNext,
  onClose,
  onChange,
  onReply,
  headingRef,
}: PanelProps & {
  ticket: Ticket
  headingRef: RefObject<HTMLHeadingElement | null>
}) {
  const [reply, setReply] = useState('')
  const [sent, setSent] = useState('')
  // A half-written reply doesn't follow you to the next ticket. (Not a
  // remount by key: that would drop focus from the next/previous buttons.)
  const [replyFor, setReplyFor] = useState(ticket.id)
  if (replyFor !== ticket.id) {
    setReplyFor(ticket.id)
    setReply('')
    setSent('')
  }
  const thread = useRef<HTMLOListElement>(null)

  function send() {
    if (!reply.trim()) return
    onReply(reply)
    setReply('')
    setSent(
      ticket.status === 'open'
        ? 'Reply sent. The ticket is now pending.'
        : 'Reply sent.',
    )
    requestAnimationFrame(() =>
      thread.current?.lastElementChild?.scrollIntoView({ block: 'nearest' }),
    )
  }

  const field = (id: string) => `${ticket.id}-${id}`

  return (
    <>
      <header className="space-y-2 border-b p-4">
        <div className="flex items-center justify-between gap-2">
          <p className="font-mono text-xs text-muted-foreground">{ticket.id}</p>
          <div className="flex items-center gap-1">
            <span className="mr-1 text-xs text-muted-foreground tabular-nums">
              {position.index + 1} of {position.total}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Previous ticket"
              disabled={!onPrevious}
              onClick={onPrevious}
            >
              <ChevronUp />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Next ticket"
              disabled={!onNext}
              onClick={onNext}
            >
              <ChevronDown />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Close ticket"
              onClick={onClose}
            >
              <X />
            </Button>
          </div>
        </div>
        <h2
          ref={headingRef}
          tabIndex={-1}
          className="text-base leading-snug font-semibold outline-none"
        >
          {ticket.subject}
        </h2>
        <p className="text-sm text-muted-foreground">
          {ticket.customer.name} · {ticket.customer.company} ·{' '}
          <span className="break-all">{ticket.customer.email}</span>
        </p>
      </header>

      <div className="flex-1 space-y-5 overflow-y-auto p-4">
        <div className="grid grid-cols-2 gap-2">
          <div className="space-y-1.5">
            <Label htmlFor={field('status')} className="text-xs">
              Status
            </Label>
            <Select
              value={ticket.status}
              onValueChange={(status) =>
                onChange({ status: status as Ticket['status'] })
              }
            >
              <SelectTrigger id={field('status')} size="sm" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {statuses.map((s) => (
                  <SelectItem key={s} value={s}>
                    {statusStyle[s].label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label htmlFor={field('priority')} className="text-xs">
              Priority
            </Label>
            <Select
              value={ticket.priority}
              onValueChange={(priority) =>
                onChange({ priority: priority as Ticket['priority'] })
              }
            >
              <SelectTrigger
                id={field('priority')}
                size="sm"
                className="w-full"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {priorities.map((p) => (
                  <SelectItem key={p} value={p}>
                    <PriorityLabel priority={p} />
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="col-span-2 space-y-1.5">
            <Label htmlFor={field('assignee')} className="text-xs">
              Assignee
            </Label>
            <Select
              value={ticket.assignee}
              onValueChange={(assignee) =>
                onChange({ assignee: assignee as Ticket['assignee'] })
              }
            >
              <SelectTrigger
                id={field('assignee')}
                size="sm"
                className="w-full"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {agents.map((a) => (
                  <SelectItem key={a} value={a}>
                    {a}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <section aria-label="Conversation" className="space-y-3">
          <h3 className="text-xs font-medium text-muted-foreground">
            Conversation
          </h3>
          <ol ref={thread} className="space-y-3">
            {ticket.messages.map((m, i) => (
              <li key={i} className="flex gap-2.5">
                <span
                  aria-hidden
                  className={cn(
                    'flex size-7 shrink-0 items-center justify-center rounded-full text-[11px] font-medium',
                    m.from === 'agent'
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-muted text-muted-foreground',
                  )}
                >
                  {initials(m.author)}
                </span>
                <div className="min-w-0 flex-1 space-y-1">
                  <p className="flex flex-wrap items-baseline gap-x-2 text-sm">
                    <span className="font-medium">{m.author}</span>
                    <span className="text-xs text-muted-foreground tabular-nums">
                      {formatTime(m.at)}
                    </span>
                  </p>
                  <p
                    className={cn(
                      'rounded-md px-3 py-2 text-sm',
                      m.from === 'agent' ? 'bg-muted/60' : 'border',
                    )}
                  >
                    {m.body}
                  </p>
                </div>
              </li>
            ))}
          </ol>
        </section>
      </div>

      <form
        className="space-y-2 border-t p-4"
        onSubmit={(e) => {
          e.preventDefault()
          send()
        }}
      >
        <Label htmlFor={field('reply')} className="sr-only">
          Reply to {ticket.customer.name}
        </Label>
        <textarea
          id={field('reply')}
          value={reply}
          onChange={(e) => {
            setReply(e.target.value)
            setSent('')
          }}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
              e.preventDefault()
              send()
            }
          }}
          rows={3}
          placeholder={`Reply to ${ticket.customer.name.split(' ')[0]}…`}
          className="w-full resize-none rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-xs outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:bg-input/30"
        />
        <div className="flex items-center justify-between gap-2">
          <p aria-live="polite" className="text-xs text-muted-foreground">
            {sent || '⌘ Enter to send'}
          </p>
          <Button type="submit" size="sm" disabled={!reply.trim()}>
            <SendHorizontal /> Send reply
          </Button>
        </div>
      </form>
    </>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { PaginationState, SortingState } from '@tanstack/react-table'

import { cn } from '#/lib/utils'
import { tickets as initialTickets } from './data'
import type { Ticket } from './data'
import { PAGE_SIZE, TicketTable, useTicketTable } from './data-table'
import { TicketPanel } from './ticket-panel'
import { inView, replyTo, updateTicket, views } from './tickets'
import type { View } from './tickets'

export function SplitDetailDemo() {
  const [tickets, setTickets] = useState<Ticket[]>(initialTickets)
  const [view, setView] = useState<View>('open')
  const [sorting, setSorting] = useState<SortingState>([
    { id: 'updated', desc: true },
  ])
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: PAGE_SIZE,
  })
  const [openId, setOpenId] = useState<string | null>(null)
  // The open ticket as it was when opened, so it keeps its place in the sort
  const [pinned, setPinned] = useState<Ticket | null>(null)
  const filters = useRef<HTMLDivElement>(null)

  function open(id: string | null) {
    setOpenId(id)
    setPinned(tickets.find((t) => t.id === id) ?? null)
  }

  const table = useTicketTable({
    tickets,
    pinned,
    view,
    sorting,
    onSortingChange: setSorting,
    pagination,
    onPaginationChange: setPagination,
    meta: { openId, view, open },
  })

  // Every ticket in the current filter and sort, across all pages
  const order = table.getPrePaginationRowModel().rows.map((r) => r.id)
  const index = openId ? order.indexOf(openId) : -1
  const ticket = tickets.find((t) => t.id === openId) ?? null

  /** Opens a neighbour, turning the page if it's on another one */
  function go(id: string) {
    open(id)
    const page = Math.floor(order.indexOf(id) / PAGE_SIZE)
    setPagination((p) => (p.pageIndex === page ? p : { ...p, pageIndex: page }))
  }

  // Bring the open row into view inside the table's own scroll area
  useEffect(() => {
    if (!openId) return
    document
      .querySelector(`[data-ticket-row="${openId}"]`)
      ?.scrollIntoView({ block: 'nearest' })
  }, [openId, pagination.pageIndex])

  // A ticket that left the filter disappears on close; don't strand the
  // page past the end
  const pageCount = table.getPageCount()
  useEffect(() => {
    if (pageCount && pagination.pageIndex >= pageCount)
      setPagination((p) => ({ ...p, pageIndex: pageCount - 1 }))
  }, [pageCount, pagination.pageIndex])

  const fallbackFocus = useCallback(
    () =>
      filters.current
        ?.querySelector<HTMLElement>('[aria-pressed="true"]')
        ?.focus(),
    [],
  )

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div
          ref={filters}
          role="group"
          aria-label="Show tickets"
          className="inline-flex rounded-md border p-0.5"
        >
          {views.map((v) => (
            <button
              key={v.id}
              type="button"
              aria-pressed={view === v.id}
              onClick={() => {
                setView(v.id)
                setPagination((p) => ({ ...p, pageIndex: 0 }))
              }}
              className="flex h-7 items-center gap-1.5 rounded px-2.5 text-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-muted aria-pressed:text-foreground"
            >
              {v.label}
              <span className="text-xs tabular-nums">
                {tickets.filter((t) => inView(t, v.id)).length}
              </span>
            </button>
          ))}
        </div>
        <p className="text-sm text-muted-foreground">
          Open a ticket by its subject.
        </p>
      </div>

      {/* The table scrolls inside this frame, and the panel opens at its
          right, pushing the table over instead of covering it */}
      <div className={cn('relative flex overflow-hidden rounded-md border')}>
        <TicketTable table={table} panelOpen={openId !== null} />
        <TicketPanel
          ticket={ticket}
          position={{ index: Math.max(index, 0), total: order.length }}
          onPrevious={index > 0 ? () => go(order[index - 1]) : undefined}
          onNext={
            index >= 0 && index < order.length - 1
              ? () => go(order[index + 1])
              : undefined
          }
          onClose={() => open(null)}
          onChange={(changes) =>
            openId && setTickets((all) => updateTicket(all, openId, changes))
          }
          onReply={(body) =>
            openId && setTickets((all) => replyTo(all, openId, 'You', body))
          }
          fallbackFocus={fallbackFocus}
        />
      </div>
    </div>
  )
}
